export function addOnsTotal(groups, selection) {
    let total = 0;
    let currency = "";
    for (const g of groups)
        for (const a of g.addOns) {
            const q = selection[a.id] ?? 0;
            if (q > 0 && a.priceAmount > 0) {
                total += a.priceAmount * q;
                currency ||= a.currency;
