/** Money as the API sends it ({ value, currency }) → display string ("" when incomplete). */
export const formatMoney = (money, locale) => formatPrice(money?.value, money?.currency, locale);
/** "1 hr 30 min" / "45 min" / "2 hr" through Intl unit formatting ("" when unknown). */
export function durationLabel(minutes, locale) {
    if (minutes == null || !Number.isFinite(minutes) || minutes <= 0)
        return "";
    try {
        const unit = (u, n) => new Intl.NumberFormat(locale, { style: "unit", unit: u, unitDisplay: "short" }).format(n);
        if (minutes < 60)
            return unit("minute", minutes);
        const hours = Math.floor(minutes / 60);
        const rest = minutes % 60;
