export function resolvePrice(raw) {
    const payment = raw.payment ?? {};
    const rateType = (RATE_TYPES.includes(payment.rateType) ? payment.rateType : "NO_FEE");
    const hasPricingPlans = (payment.pricingPlanIds ?? []).length > 0;
    let price = "";
    let priceFrom = false;
    let free = false;
